import{_ as l,C as r,o as t,c as o,j as e,a as i,E as n,a6 as h}from"./chunks/framework.CnPv4DE1.js";const A=JSON.parse('{"title":"普通人将如何借助 AI 实现财富自由","description":"","frontmatter":{"title":"普通人将如何借助 AI 实现财富自由","originalTitle":"How Average People Will Get Rich With AI","date":"2025-05-27","originalUrl":"https://thedankoe.com/letters/how-average-people-will-get-rich-with-ai/","minutes":15,"sourceHash":"9e7cbb3c0080968485ff6ab56612629d98e209ea254404d1a294c8b42bf3d3f3","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-average-people-will-get-rich-with-ai/"}]]},"headers":[],"relativePath":"letters/how-average-people-will-get-rich-with-ai.md","filePath":"letters/how-average-people-will-get-rich-with-ai.md"}'),s={name:"letters/how-average-people-will-get-rich-with-ai.md"};function c(u,p,d,b,m,f){const a=r("ArticleMeta");return t(),o("div",null,[p[0]||(p[0]=e("h1",{id:"普通人将如何借助-ai-实现财富自由",tabindex:"-1"},[i("普通人将如何借助 AI 实现财富自由 "),e("a",{class:"header-anchor",href:"#普通人将如何借助-ai-实现财富自由","aria-label":'Permalink to "普通人将如何借助 AI 实现财富自由"'},"​")],-1)),n(a),p[1]||(p[1]=h('<p>你想变得富有。</p><p>每个人都想。</p><p>而且你想快点做到。</p><p>但你也想享受自己所做的事。你想要意义。你想掌控自己工作多长时间，这样你才能优先安排生活中的其他领域。</p><p>我有好消息和坏消息。</p><p>好消息是，这是可能的。</p><p>没人愿意承认自己找到并利用了捷径，但这正是我们当今世界充斥的东西。</p><p>数字产品是一条捷径。</p><p>社交媒体是一条捷径。</p><p>AI 是一条捷径。</p><p>整个科技本身就是一条捷径。</p><p>如果你不喜欢“捷径”这个词，把它换成“杠杆”也行。</p><p>你不再需要通过邮件寄送实体信件了，因为你可以发一条 Instagram reel，在车里表达自己的想法，就能触达 50 万人。（50 万已经很疯狂了。你甚至不需要 1 万人。你还可以直接私信任何人，太离谱了。）</p><p>你不再需要去图书馆找一本书来获取某个超具体的信息，因为你只需和 AI 简单对话一下，就能理清思路。</p><p>你不再需要浪费 1 万美元以上去测试一个实体产品是否有市场，因为你可以在 2 周内针对同一主题上线一个数字产品，看它是否有效，产生现金流，然后把这笔钱和被验证过的想法投入到另一个商业模式中。</p><p>坏消息是：</p><p>你仍然需要学会如何走这条捷径。</p><p>而捷径并不等同于成功的保证。</p><p>人类总是会从这条更短的路上分心，因为他们无法坐下来专注。</p><p>即便我们已经拥有如此强大的 AI，很多人依然会失败，原因很简单：他们尝试了 2 周就放弃了，因为他们一开始就没认真对待这件事。</p><p>对于那些明白“没有失败就没有成功”这一点的人来说，我们开始吧。</p><h2 id="一般人如何变富" tabindex="-1">一般人如何变富 <a class="header-anchor" href="#一般人如何变富" aria-label="Permalink to &quot;一般人如何变富&quot;">​</a></h2><p>首先，我们需要理解一般意义上如何变富。</p><p>假设你还不富有，或者你只是为了好玩才读这篇文章，有 4 种方式：</p><ul><li>每月储蓄一部分收入（慢）</li><li>每月把一部分收入投资到股票或房地产（不那么慢）</li><li>建立一个你自己掌控收入的现金流业务，然后再储蓄或投资（更不那么慢）</li><li>把大量现金投入到企业、股票或房地产中（这留给那些手头现金充裕的人）</li></ul><p>基础常识。妈妈都教过我们这些。但大多数人手头并没有闲钱。</p><p>然而，大多数人有时间。</p><p>值得庆幸的是，第 3 种方式是任何人都能做到的。</p><p>这正是你可以用来<em>开启</em>自己致富之路的选项。</p><p>如果你对其他几种方式感兴趣，那我帮不了你。</p><p>话虽如此，你必须建立一个企业。</p><p>AI 只是一种方式，让你作为一个人（或一个小团队）能够做得更多、更快。</p><p>很遗憾地告诉你，这不是又一个一夜暴富的骗局。它是一条捷径，通往那些<em>已经行之有效</em>并被证明有效的事情。几乎每一个“用 AI 致富”的视频都会给你一个花里胡哨的新工具，但这恰恰是确保它永远无效的万全之策。</p><p>我们一直在谈论的那条捷径，就是启动一个 AI 优先型企业。</p><p>因此，有几件事你需要知道：</p><h3 id="_1-现在每一家企业都是一家媒体公司。" tabindex="-1">1）现在每一家企业都是一家媒体公司。 <a class="header-anchor" href="#_1-现在每一家企业都是一家媒体公司。" aria-label="Permalink to &quot;1）现在每一家企业都是一家媒体公司。&quot;">​</a></h3><p>这意味着从电商到数字产品再到本地企业的每一家企业，都在发布网络内容来宣传自己的业务。</p><p>这意味着你也必须这么做。</p><p>这就是你吸引潜在客户为你付费的方式。</p><p>付费广告、SEO 以及赞助播客之类的其他方式都是可行的营销手段，但在我看来，有机内容才是你建立人们信任的长期<em>品牌</em>的方式。尤其是在如今这个社交媒体优先的世界里。</p><p>随着互联网充斥着 AI 生成的垂料，这一点只会变得更加重要。</p><h3 id="_2-最大的差异化因素是你自己。" tabindex="-1">2）最大的差异化因素是<em>你自己。</em> <a class="header-anchor" href="#_2-最大的差异化因素是你自己。" aria-label="Permalink to &quot;2）最大的差异化因素是*你自己。*&quot;">​</a></h3><p>个人品牌不只是另一个一时的潮流。</p><p>是的，“个人品牌”这个概念听起来有点尴尬。</p><p>但它的本质是美好的，那就是<em>因为做自己而获得报酬。</em></p><p>我们并不是要打造一个个人品牌，我们是在利用现代科技，去更少地工作、更多地赚钱，并专注于我们真正在意的话题。我们是在把互联网当作一个载体，来建立我们一生的事业。</p><p>不，你不需要露脸。</p><p>不，你不需要使用真名。</p><p>但你确实需要一个故事、一种个性（即便像我一样无趣！），以及一个帮助他人的使命。</p><p>因为人们只会向他们信任的人购买东西。</p><p>当 AI 开始让互联网充斥着那些急于快速捞钱、却没意识到这总会反噬自己的人所制造的不可信内容时，信任变得稀缺。</p><p>你，作为一个人——你的问题、经历、观点和兴趣——正是在当今世界让你脱颖而出的东西。</p><p>就我而言，一个普通的“品牌”或企业，只要满足这些条件，也可以算作个人品牌。也就是说，只要它是你自身的延伸。</p><p>你不必创建一个个人品牌才能致富，<strong>但你需要一家有个性的企业。</strong></p><p>这正是我们要学习的内容。</p><h3 id="_3-大多数新手应该从数字产品开始。" tabindex="-1">3）大多数新手应该从数字产品开始。 <a class="header-anchor" href="#_3-大多数新手应该从数字产品开始。" aria-label="Permalink to &quot;3）大多数新手应该从数字产品开始。&quot;">​</a></h3><p>我们不再生活在那种你把毕生积蓄砸进一个生意、然后祈祷人们会想要你卖的东西的世界里了。</p><p>相反，你应该这样做：</p><ul><li>用社交内容测试想法</li><li>把效果最好的想法快速转化成一个数字产品</li><li>通过反馈改进产品</li><li>把这个产品扩展成不同的报价</li></ul><p>数字产品可以是任何东西，从电子书到课程，再到解决单一问题的小型软件。很多人正在用像 Cursor 这样的工具编写细分领域的应用（不是那种全面的企业级软件）。我自己还没做过这个，不过我很想尽快做一个用于散步的游戏化 App，所以在这封信里我们不打算专注于这个选项。</p><p>我的《2 小时写作者》课程为我带来了资金和被验证过的想法，让我得以建立 Kortex——一个成本更高、由开发团队支撑的软件业务。</p><p>如果我愿意，我甚至可以更进一步，卖一款面向网络写作者的键盘、一支实体笔，或其他配件。</p><p>如果我有一个健康类数字产品，我可以像现在很多人在 X 和 IG 上做的那样，推出一款补剂，但基于我自己的哲学理念，给它一个独特的转折。</p><p>而这里有意思的地方在于，你已经有一批从你的产品中获益的人了。这意味着他们中很多人很可能会继续投资你接下来做的任何东西。</p><p>当然，你完全可以不必在数字产品之外走得更远。</p><p>它们拥有惊人的利润率，能让你规模化地帮助人们，同时享受科技赋予你的自由时间。</p><p><strong>注意</strong>：个人品牌不是一种商业模式，它是<em>为</em>企业服务的信任机制。作为新手，我们正在构建的<em>模式</em>是围绕数字产品展开的，尽管你几乎可以将任何东西变现。</p><h3 id="_4-这就让我们剩下了-4-个重点领域" tabindex="-1">4）这就让我们剩下了 4 个重点领域 <a class="header-anchor" href="#_4-这就让我们剩下了-4-个重点领域" aria-label="Permalink to &quot;4）这就让我们剩下了 4 个重点领域&quot;">​</a></h3><p>启动一个现代企业，你需要 4 项技能。</p><ol><li><strong>内容</strong> ——因为这是一家媒体公司，而媒体正是你吸引潜在客户的方式（没有客户，就没有生意）。</li><li><strong>品牌</strong> ——因为凭什么他们要信任<em>你？</em>为什么互联网上的陌生人会对你所帮助他们解决的问题产生共鸣？</li><li><strong>产品</strong> ——这点很明显，因为没有产品你就赚不到钱，或者只能拿到一小部分收入（赞助、平台分成、联盟营销）</li><li><strong>推广</strong> ——如果你不在你的品牌和内容之下推广你的产品，它永远不会被人看到。</li></ol><p>值得庆幸的是，所有这些都可以快速学会，做到足够高的质量，并借助 AI 部分实现自动化。</p><p>我说的不是一个拥有人力资源部门和其他运营职能的成熟公司。我说的是一个普通人在 AI 加持下能够做到的事情。</p><p>这正是我们在这里要学习的内容。</p><p><strong>注意</strong>：为期 30 天打造盈利个人品牌的挑战活动将于 6 月 16 日开始。如果你想要每天的课程、行动步骤，以及每天只需 30-60 分钟的 AI 提示词，<a href="https://stan.store/thedankoe/p/build-a-profitable-personal-brand-in-30-days" target="_blank" rel="noreferrer">点击这里加入</a>。到结束时，你将掌握一整套现代高价值技能，以及一个盈利品牌的基础。</p><h2 id="打造一家-ai-优先的一人媒体公司" tabindex="-1">打造一家 AI 优先的一人媒体公司 <a class="header-anchor" href="#打造一家-ai-优先的一人媒体公司" aria-label="Permalink to &quot;打造一家 AI 优先的一人媒体公司&quot;">​</a></h2><p>我不想只是给你一些提示词，让 AI 替你把这件事做完。</p><p>相反，我想给你一些更强大的东西：</p><p>一种能借助 AI <em>弄清楚任何事情</em>的方法。</p><p>所以，我不打算准确告诉你该做什么，而是要向你展示我会如何从零开始，弄清楚怎样创建品牌、内容、产品和推广。</p><p>如果你坚持读下去，你所收获的，会远远超过你自己单独摸索所能找到的一切。</p><h3 id="品牌——打造一个个人品牌教练" tabindex="-1">品牌——打造一个个人品牌教练 <a class="header-anchor" href="#品牌——打造一个个人品牌教练" aria-label="Permalink to &quot;品牌——打造一个个人品牌教练&quot;">​</a></h3><p>让我们假设你什么都不知道。</p><p>你不知道什么是个人品牌，也不知道是什么让它有效。</p><p>你所知道的，仅仅是你在这封信中读到的内容。你意识到了一个机会，你想尽快利用它。</p><p>但事情是这样的。</p><p>对于像打造个人品牌这样的事情，有一千种不同的方法可以做到。每个人都有自己的一套建立方式。它们都有效，但有时它们并不符合你的目标。</p><p>如果你只是让 AI 帮你打造一个，你可能不会有太大进展。智能需要上下文。</p><p>以下是我会怎么做：</p><ol><li>找到一个你信任、教授个人品牌的专家</li><li>把他们的建议输入 AI，并浓缩成一份详细的行动计划</li><li>把它转化成一个能指导你、让你保持专注的提示词</li></ol><p>对于第 1 步，你要找的信息不仅要可信，还要足够详细，才能得到结果。</p><p>你可以在一本以 PDF 形式存在的书、一个 YouTube 视频、免费指南、课程或文章中找到这类信息。</p><p>在我看来，找到这类信息最好的地方是 YouTube。</p><p>在 YouTube 上搜索了一番：</p><ul><li>“如何打造一个盈利的个人品牌”</li><li>“个人品牌 Alex Hormozi”</li><li>“打造个人品牌完整指南”</li></ul><p>我找到了几个看起来不错的视频。但有一个 <a href="https://youtu.be/Ch4Sl0POBhU" target="_blank" rel="noreferrer">Caleb Ralston 的 6 小时视频</a>（他是 Gary V 和 Alex Hormozi 背后的操盘手），所以我们就用这个。</p><p>以下是我会给 AI 输入的提示词：</p><blockquote><p>我想打造一个个人品牌。把这个视频拆解成一份详尽的行动计划。写这份行动计划时，请当作你在从零教我如何打造一个个人品牌。</p><p>[视频链接]</p></blockquote><p>我个人是在 <a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a> 里做的这件事，因为它可以从 YouTube 转录文本中提取内容，而且你可以为不同任务选择不同的 AI 模型。</p><p>我用的是 Gemini 2.5 Pro，因为它是一个推理模型，能处理大量上下文（一个 6 小时的视频信息量很大）。</p><p>输出结果是一份<a href="https://app.kortex.co/public/document/41aa3a5d-6e91-4fcf-ac27-388c3fbb95d2" target="_blank" rel="noreferrer">极其详尽的指南</a>，这正是我们想要的。</p><p>现在，我们怎样才能把这个变成可以用来打造<em>我们自己</em>个人品牌的东西呢？</p><p>首先，你需要把 AI 不仅当作一个帮你学习如何做某件事的工具，还要把它当作一个能根据你提供的信息为你完成工作的工具。</p><p>所以，我们要把这份个人品牌指南变成一个两阶段的提示词。</p><p>我已经说过很多次了，但我强烈建议你使用一个能帮你按照最佳实践创建优质提示词的提示词。</p><p>在 Kortex 中，你可以进入<strong>Chat</strong>，点击<strong>Write Incredible AI Prompts</strong>。</p><p>然后，你输入并发送的任何内容都会被转化为一个提示词。</p><p>或者，你可以<a href="https://app.kortex.co/public/document/83651c0d-dfd3-4e6c-9821-c9c41b2a3ddc" target="_blank" rel="noreferrer">在这里复制这个提示词</a>，粘贴到你正在使用的任何工具中并发送。</p><p>现在，输入这个：</p><blockquote><p>我想创建一个作为我的个人品牌教练的 AI 提示词。</p><p>把你的提示词结构分成两个阶段。</p><p>第一阶段——收集背景信息：每次问用户一个问题，获取建立个人品牌所需的所有细节。在第一阶段结束时，提供一份详细的分步行动计划</p><p>第二阶段——个人品牌教练：从用户应该为其个人品牌采取的第一组可执行步骤开始，并鼓励用户就他们已经完成的所有工作频繁反馈。每次反馈时，给他们提出让工作更有影响力的建议，并跟进下一组可执行步骤。</p><p>把提示词的每个阶段都建立在这份关于个人品牌打造的信息之上：</p><p>[把上一个提示词的回复粘贴在这里]</p></blockquote><p>使用像 Gemini 2.5 Pro 这样的推理模型时，输出结果相当惊人。<a href="https://app.kortex.co/public/document/186f6630-7328-4cad-9590-ccfa4b3a76fd" target="_blank" rel="noreferrer">在这里</a>。极其全面。（我确实需要稍微清理一下，你这样做的时候一定要通读一遍输出内容。）</p><p>现在，把那个提示词发送到一个新对话中，花大量时间回答第一阶段的问题。</p><p>恭喜你，现在你有了一份个性化策略和专属的个人品牌专家教练，而且没花 10,000 美元，只用了 30 分钟，而不是看视频要花的 6 个小时，再加上自己规划一切要花的 20 个小时。</p><p>至少每周和你的“教练”反馈一次，它会慢慢引导你走向更精细的行动和变现方式。</p><h3 id="内容——用你自己的策略复制有效的方法" tabindex="-1">内容——用你自己的策略复制有效的方法 <a class="header-anchor" href="#内容——用你自己的策略复制有效的方法" aria-label="Permalink to &quot;内容——用你自己的策略复制有效的方法&quot;">​</a></h3><p>既然你已经从上一部分得到了个人行动计划，你现在知道：</p><ul><li>你要从哪个平台开始</li><li>你要创作什么类型的内容</li><li>每天或每周发布的频率</li></ul><p>现在，我们需要学习如何写内容。</p><p>这里有几个不同的步骤可以采用。</p><p>我认为你会对输出结果感到惊讶：</p><p><strong>1）根据你的行动计划生成一份内容创意清单。</strong></p><p>我们需要一些相关的内容创意来使用。</p><p>最好是那些已被证明有效的。</p><p>在新对话中试试这个提示词：</p><blockquote><p>根据我的个人品牌策略生成 30 个经过验证的内容创意：[链接上一步的个人品牌策略文档]</p><p>这些创意应该在高表现力和权威性之间取得平衡，从我受众的痛点、我细分领域中的热门话题，以及让我区别于其他品牌的独特视角中提取。</p></blockquote><p>我把评判这些创意质量的事留给你自己。</p><p><strong>2）拆解高表现力的帖子结构。</strong></p><p>这取决于你正在增长的平台和内容媒介。</p><p>如果我在 YouTube 上做增长，我会：</p><ul><li>去我的细分领域中一个热门账号</li><li>按最受欢迎筛选他们的视频</li><li>找到一个你想模仿的风格的视频</li></ul><p>然后，在新对话中让 AI 拆解它：</p><blockquote><p>给我一份关于这个视频为什么有效的全面拆解：</p><ul><li>整个视频的结构作为一个框架</li><li>用来抓住注意力的心理模式</li><li>每个部分的想法结构以及它们为什么有影响力</li></ul><p>把你的输出组织成好像你在一步一步教我如何重新创作这个视频。</p></blockquote><p>你可以通过把多条推文、LinkedIn 帖子、通讯或短视频脚本粘贴到 AI 中来完成同样的事情。</p><p>一旦你详细拆解了<em>为什么那种内容结构表现良好</em>，你就可以用之前的流程把它变成一个提示词。</p><p>首先，去 <a href="https://kortex.co/" target="_blank" rel="noreferrer">Write Incredible AI Prompts</a> 工作流，或者把提示词创建器的提示词粘贴到一个新对话中。</p><p>把之前的视频拆解输出喂给它，告诉它你想创建一个提示词，用来按照那个高表现力的结构生成 YouTube 视频大纲（第一阶段）和 YouTube 视频脚本（第二阶段）。</p><p><strong>3）用那个提示词，配合你自己的创意来创作内容</strong></p><p>到目前为止，你有了一份 30 个内容创意的清单，以及一个能引导你创作实际内容的提示词。</p><p>现在你只需要：</p><ul><li>发送你的内容创作提示词</li><li>给它你想变成内容的创意</li></ul><p>这里有一个<a href="https://app.kortex.co/public/document/35506957-e550-40f7-9d0f-c9a116561276" target="_blank" rel="noreferrer">推文写作提示词</a>的例子，它是我根据一个教如何写推文的 YouTube 视频创建的。</p><p>基于我们学到的东西，你已经有了用 AI 做任何你想做的事的流程，所以我把实验的部分留给你自己。</p><p>最后一件事。</p><p>既然教这个要花一整篇文章，那说明优质内容不仅仅是写社交帖子。你需要为人们“打造一个世界”的内容，让他们沉浸式地追看和探索。<a href="https://thedankoe.substack.com/p/how-to-build-a-world-the-2-hour-content" target="_blank" rel="noreferrer">我在这里教过这个。</a></p><h3 id="产品——像-ai-艺术家一样-偷师" tabindex="-1">产品——像 AI 艺术家一样“偷师” <a class="header-anchor" href="#产品——像-ai-艺术家一样-偷师" aria-label="Permalink to &quot;产品——像 AI 艺术家一样“偷师”&quot;">​</a></h3><p>关于 AI，有件事我要说。</p><p>对于高度个人化的东西，我不信任一个泛泛的回答。</p><p>当然，如果你问 AI 今天天气怎么样（尽管大多数基础模型由于知识截止日期，如果不搭配联网搜索是回答不了这个问题的），那就随便问吧。</p><p>但当涉及到这样的事情时：</p><ul><li>有不止一种“正确”的做法</li><li>结果由独特性和新颖性决定</li><li>输出需要来自你自己大脑的特定知识</li></ul><p>那你就不能跳过学习的过程。</p><p>这对你来说是好消息，因为那些想“快速致富”的人会摔个大跟头。</p><p>但 AI 的另一件事是，只要用对提示词，你可以把它变成一个专家。你不<em>需要</em>是一个经验丰富的营销人员，AI 就能把你的想法变成一个传奇营销人员会使用的东西。</p><p>到目前为止，我们知道如何用 AI 把有效的东西拆解成一份详细的指南。我们也知道如何把它变成一个能替你执行任务的提示词。最后，我们知道我们需要找到一个专家级灵感的来源，这样我们才能给 AI 提供上下文，让它从中执行任务。</p><p>所以，这里有几件事你可以做：</p><ol><li>找一个解释初学者最适合出售哪种数字产品类型的 YouTube 视频——把它变成一个能采访你、找出哪种最适合的提示词。</li><li>根据产品类型（电子书、课程、训练营、模板），问 AI 你应该围绕什么主题创建产品——把你之前的个人品牌策略作为上下文喂给它。</li><li>让 AI 给你一份关于 Alex Hormozi 的报价创建框架的全面拆解。把它变成一个能引导你从产品创意中创建自己报价的提示词。</li><li>把像 Eugene Schwartz 的《Breakthrough Advertising》这样的 PDF 拆解成一份写落地页文案的全面指南。把它变成一个提示词来写你的落地页，并给它你的报价（我上周在<a href="/letters/how-smart-creators-will-make-money-in-2026-youre-early">未来数字产品的信中</a>也谈过如何做这件事）。</li><li>找一个有类似产品的人，购买它，把每个部分粘贴到 AI 中来拆解产品的结构。把它变成一个能引导你创建一个类似产品、但用你自己想法的提示词。</li></ol><p>这一切相当繁琐，但那正是因为你真的要脱颖而出，让这一切奏效。</p><h3 id="推广——重复这个流程" tabindex="-1">推广——重复这个流程 <a class="header-anchor" href="#推广——重复这个流程" aria-label="Permalink to &quot;推广——重复这个流程&quot;">​</a></h3><p>你 AI 优先的业务能否成功，取决于毫不害羞、系统化的自我推广。</p><p>你有一个个人品牌策略。</p><p>你在和你的教练反馈，让它引导你成长。</p><p>你在按每周计划发布高表现力的内容。</p><p>你有一个可以开始销售的产品（如果你不知道怎么收款，可以<a href="https://join.stan.store/thedankoe" target="_blank" rel="noreferrer">放到 Stan 上</a>）。</p><p>现在，你需要在<em>你的内容中</em>推广你的产品。</p><p>这意味着：</p><ul><li>在每个 YouTube 视频描述中链接你的产品</li><li>每天在一条推文、Thread、LinkedIn 帖子的回复中，或者你的 Instagram 故事中，植入你的产品</li><li>在 Shorts、Reels 和 TikToks 中引导人们去看你的个人简介链接</li></ul><p>这一切都取决于你选择从哪个平台开始。</p><p>现在，我想留给你最后一件事。因为大多数人不懂怎么推广。</p><p>如果你的内容足够好，有时候简单一句“通过描述里的链接来看看我的产品”就够了，但当你在类似回复推文这样的地方推广时，你需要更具体一点。</p><p>试试这些提示词：</p><blockquote><p>在社交媒体上推广我的产品，最有效的文案框架是什么？</p></blockquote><p>这应该会给你一些框架，比如 PAS 和 AIDA。</p><p>如果你愿意，可以问问为什么那些框架有效，以及背后的心理学原理。然后问：</p><blockquote><p>这是我的产品详情：[链接或粘贴你的产品详情]</p><p>用 PAS 框架和直接反应营销原则，给我写三条不超过 280 字符的推广文案。这些推广文案应该链接到我的产品。</p></blockquote><p>从那开始，你可以进行测试和迭代。</p><p>每天轮流使用这些文案，测试不同的变体，看哪个能让更多人点击进去查看你的产品。</p><p>关于这篇信件，我们还可以讲很多东西，但我打算就此收笔。我很有信心，我已经给了该看到这些内容的人足够的东西去实践。</p><p>感谢阅读。</p><p>——Dan</p><h3 id="如果你想进一步深入" tabindex="-1">如果你想进一步深入： <a class="header-anchor" href="#如果你想进一步深入" aria-label="Permalink to &quot;如果你想进一步深入：&quot;">​</a></h3><ul><li>“30 天打造盈利个人品牌”挑战赛将于 6 月 16 日开始。如果你想要 30 天的每日课程和行动步骤，帮你获得第一批粉丝和第一笔收入，<a href="https://stan.store/thedankoe/p/build-a-profitable-personal-brand-in-30-days" target="_blank" rel="noreferrer">请在报名截止前加入。</a></li><li>我们现在在<a href="https://thedankoe.substack.com/" target="_blank" rel="noreferrer">不断扩充的高级资料库中</a>提供了一份创建数字产品的超级指南，包括如何为该产品撰写落地页文案，以及如何推出这个产品。</li></ul><hr><p><a href="/en/letters/how-average-people-will-get-rich-with-ai">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',182))])}const g=l(s,[["render",c]]);export{A as __pageData,g as default};
